CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('customer','supplier','admin','support')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers(id TEXT PRIMARY KEY,user_id TEXT UNIQUE REFERENCES users(id),name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','suspended')),registration TEXT NOT NULL DEFAULT '',commission_bps INTEGER NOT NULL DEFAULT 0 CHECK(commission_bps BETWEEN 0 AND 5000),connector TEXT NOT NULL DEFAULT 'direct');
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS pricing_rules(id TEXT PRIMARY KEY, category_id TEXT REFERENCES categories(id),markup_bps INTEGER NOT NULL DEFAULT 2000 CHECK(markup_bps BETWEEN 0 AND 10000),fixed_kobo INTEGER NOT NULL DEFAULT 0 CHECK(fixed_kobo>=0),discount_bps INTEGER NOT NULL DEFAULT 0 CHECK(discount_bps BETWEEN 0 AND 9000),minimum_profit_kobo INTEGER NOT NULL DEFAULT 10000 CHECK(minimum_profit_kobo>=0));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,supplier_id TEXT NOT NULL REFERENCES suppliers(id),category_id TEXT NOT NULL REFERENCES categories(id),name TEXT NOT NULL,description TEXT NOT NULL,brand TEXT NOT NULL DEFAULT 'Ahiakom Demo',image TEXT NOT NULL DEFAULT '/products/headphones.svg',cost_kobo INTEGER NOT NULL CHECK(cost_kobo>0),stock INTEGER NOT NULL CHECK(stock>=0),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS cart(user_id TEXT NOT NULL REFERENCES users(id),product_id TEXT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20),PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS wishlist(user_id TEXT NOT NULL REFERENCES users(id),product_id TEXT NOT NULL REFERENCES products(id),PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending_payment',subtotal_kobo INTEGER NOT NULL,shipping_kobo INTEGER NOT NULL,total_kobo INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'NGN',address JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),supplier_id TEXT NOT NULL REFERENCES suppliers(id),name TEXT NOT NULL,quantity INTEGER NOT NULL,cost_kobo INTEGER NOT NULL,price_kobo INTEGER NOT NULL,supplier_due_kobo INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS fulfilments(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),supplier_id TEXT NOT NULL REFERENCES suppliers(id),status TEXT NOT NULL DEFAULT 'pending_payment',tracking TEXT NOT NULL DEFAULT '',UNIQUE(order_id,supplier_id));
CREATE TABLE IF NOT EXISTS payments(reference TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),provider TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',amount_kobo INTEGER NOT NULL,fees_kobo INTEGER NOT NULL DEFAULT 0,provider_id TEXT UNIQUE,authorization_url TEXT,verified_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),amount_kobo INTEGER NOT NULL CHECK(amount_kobo>0),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested',provider_id TEXT UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,fulfilment_id TEXT NOT NULL UNIQUE REFERENCES fulfilments(id),status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,available_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category_id);
CREATE INDEX IF NOT EXISTS orders_user_idx ON orders(user_id,created_at);
CREATE INDEX IF NOT EXISTS fulfilments_supplier_idx ON fulfilments(supplier_id);
CREATE INDEX IF NOT EXISTS outbox_pending_idx ON outbox(status,available_at);
CREATE TABLE IF NOT EXISTS settlements(id TEXT PRIMARY KEY,fulfilment_id TEXT NOT NULL UNIQUE REFERENCES fulfilments(id),supplier_id TEXT NOT NULL REFERENCES suppliers(id),amount_kobo INTEGER NOT NULL CHECK(amount_kobo>0),provider_reference TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'simulated',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS order_costs(order_id TEXT PRIMARY KEY REFERENCES orders(id),shipping_kobo INTEGER NOT NULL DEFAULT 0 CHECK(shipping_kobo>=0),tax_kobo INTEGER NOT NULL DEFAULT 0 CHECK(tax_kobo>=0),other_kobo INTEGER NOT NULL DEFAULT 0 CHECK(other_kobo>=0),note TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS support_tickets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')),reply TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE pricing_rules ADD COLUMN IF NOT EXISTS shipping_subsidy_kobo INTEGER NOT NULL DEFAULT 0 CHECK(shipping_subsidy_kobo>=0);
ALTER TABLE pricing_rules ADD COLUMN IF NOT EXISTS tax_bps INTEGER NOT NULL DEFAULT 0 CHECK(tax_bps BETWEEN 0 AND 10000);
ALTER TABLE pricing_rules ADD COLUMN IF NOT EXISTS other_cost_kobo INTEGER NOT NULL DEFAULT 0 CHECK(other_cost_kobo>=0);
ALTER TABLE products ADD COLUMN IF NOT EXISTS group_key TEXT NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN IF NOT EXISTS variant_label TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS return_requests(id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','received','rejected')),note TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
